data.diagramCode:
graph TD
    A[Start: Complex Numbers z₁ = a+ib, z₂ = c+id] --> B{Choose Operation};
    B -- Addition --> C[Identify Real (a, c) and Imaginary (b, d) Parts];
    C --> D[Add Real Parts: (a+c)];
    C --> E[Add Imaginary Parts: (b+d)];
    D & E --> F[Result: (a+c) + i(b+d)];
    B -- Multiplication --> G[Apply Distributive Property (FOIL)];
    G --> H[Expand: ac + iad + ibc + i²bd];
    H --> I{Substitute i² = -1};
    I --> J[Simplify to: ac + iad + ibc - bd];
    J --> K[Combine Real & Imaginary Terms: (ac-bd) + i(ad+bc)];
    F & K --> L[End];
